package com.ptraam.tracker;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.text.*;import java.util.*;
public final class TripActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);if(!Session.valid(this)){startActivity(new Intent(this,LoginActivity.class));finish();return;}setContentView(R.layout.activity_trip);findViewById(R.id.trip_back).setOnClickListener(v->finish());findViewById(R.id.trip_open_controls).setOnClickListener(v->{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();});refresh();}
 @Override public void onResume(){super.onResume();refresh();}private void refresh(){boolean active=TripService.running!=null;((TextView)findViewById(R.id.trip_screen_status)).setText(active?"TRIP ACTIVE":"No active trip");long started=getSharedPreferences("dashboard-state",0).getLong("tripStartedAt",0);int queued=0;try(Queue q=new Queue(this)){queued=q.count(Session.account(this));}String details=active?"GPS: "+getSharedPreferences("tracking-state",0).getString("gpsStatus","GPS Active")+(started>0?"\nStarted: "+new SimpleDateFormat("h:mm a",Locale.getDefault()).format(new Date(started)):"")+"\nPending GPS points: "+queued:"Start and end controls use the existing Fieldora trip service.";((TextView)findViewById(R.id.trip_screen_details)).setText(details);((Button)findViewById(R.id.trip_open_controls)).setText(active?R.string.end_trip:R.string.start_trip);}
}
